import * as fs from 'fs';
import * as path from 'path';
import { parse } from 'csv-parse/sync';

async function main() {
  const records = parse(csvData, {
    columns: true,
    skip_empty_lines: true,
    delimiter: ';'
  });

  let updatedCount = 0;
  for (const record of records as any[]) {
    const code = record['Código'] || record['Cdigo'];
    if (!code) continue;

    const capacity = record['Capacidade'];
    const capacityDescription = record['Descrição'];
    const func = record['Função'];
    const subfunction = record['Subfunção'];
    const knowledgeObject = record['OC'];
    const subtheme = record['Subtema'];

    const updateData: any = {
      capacity: capacity || null,
      capacityDescription: capacityDescription || null,
      function: func || null,
      subfunction: subfunction || null,
      knowledgeObject: knowledgeObject || null,
      subtheme: subtheme || null,
    };

    if (knowledgeObject) updateData.subject = knowledgeObject;
    if (subtheme) updateData.topic = subtheme;

    try {
      await prisma.question.update({
        where: { code },
        data: updateData
      });
      updatedCount++;
    } catch (e) {
      console.log(`Question ${code} not found or failed to update.`);
    }
  }

  console.log(`Finished! Updated ${updatedCount} questions.`);
}

main().catch(console.error).finally(() => prisma.$disconnect());
